CUDA_CPP_SRC = r"""
# <<<IMPROVE:cuda_cpp>>>
#include <torch/extension.h>

torch::Tensor conv1_specialized_cuda(
    torch::Tensor input,
    torch::Tensor weight,
    torch::Tensor bias);

PYBIND11_MODULE(TORCH_EXTENSION_NAME, m) {
    m.def("conv1_specialized_cuda", &conv1_specialized_cuda, "Specialized conv1 CUDA kernel");
}
# <<<END_IMPROVE>>>
"""

CUDA_CU_SRC = r"""
# <<<IMPROVE:cuda_cu>>>
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>

// Specialized direct convolution kernel for:
//   Cin=3, Cout=96, K=11, stride=4, pad=2, dilation=1, groups=1
// Input:  [N, 3, 224, 224] NCHW float32
// Output: [N, 96, 55, 55]  NCHW float32
//
// Block: (TILE_OW, TILE_OH, 1) threads
// Grid:  (ceil(OW/TILE_OW), ceil(OH/TILE_OH), N*OC_BLOCKS)
// Each block computes a TILE_OH x TILE_OW tile of outputs for a block of output channels.

#define CIN 3
#define KH 11
#define KW 11
#define STRIDE 4
#define PAD 2
#define OUT_H 55
#define OUT_W 55
#define OUT_C 96

// Tile dimensions for output spatial
#define TILE_OW 8
#define TILE_OH 4
// Output channels per block
#define OC_BLOCK 8

__global__ void conv1_direct_kernel(
    const float* __restrict__ input,   // [N, 3, 224, 224]
    const float* __restrict__ weight,  // [96, 3, 11, 11]
    const float* __restrict__ bias,    // [96]
    float* __restrict__ output,        // [N, 96, 55, 55]
    int N, int IH, int IW)
{
    // Grid mapping:
    //   blockIdx.x -> tile column in output W
    //   blockIdx.y -> tile row in output H
    //   blockIdx.z -> n * OC_BLOCKS + oc_block_idx
    int oc_blocks = (OUT_C + OC_BLOCK - 1) / OC_BLOCK;
    int n         = blockIdx.z / oc_blocks;
    int oc_block  = blockIdx.z % oc_blocks;
    int oc_start  = oc_block * OC_BLOCK;

    int ow_start  = blockIdx.x * TILE_OW;
    int oh_start  = blockIdx.y * TILE_OH;

    int tw = threadIdx.x; // 0..TILE_OW-1
    int th = threadIdx.y; // 0..TILE_OH-1

    int ow = ow_start + tw;
    int oh = oh_start + th;

    // Shared memory for input patch needed by this tile:
    // Input region: top-left = (oh_start*STRIDE - PAD, ow_start*STRIDE - PAD)
    // Size: (TILE_OH-1)*STRIDE + KH  x  (TILE_OW-1)*STRIDE + KW
    const int SH = (TILE_OH - 1) * STRIDE + KH;  // (4-1)*4+11 = 23
    const int SW = (TILE_OW - 1) * STRIDE + KW;  // (8-1)*4+11 = 39

    // Shared memory: [CIN][SH][SW]
    __shared__ float smem[CIN][23][39];

    // Cooperatively load input patch into shared memory
    int ih_base = oh_start * STRIDE - PAD;
    int iw_base = ow_start * STRIDE - PAD;
    int total_elems = CIN * SH * SW;
    int tid = th * TILE_OW + tw;
    int block_threads = TILE_OH * TILE_OW;
    const float* inp_n = input + n * CIN * IH * IW;

    for (int idx = tid; idx < total_elems; idx += block_threads) {
        int c  = idx / (SH * SW);
        int rem = idx % (SH * SW);
        int si = rem / SW;
        int sj = rem % SW;
        int ih = ih_base + si;
        int iw = iw_base + sj;
        float val = 0.0f;
        if (ih >= 0 && ih < IH && iw >= 0 && iw < IW) {
            val = inp_n[c * IH * IW + ih * IW + iw];
        }
        smem[c][si][sj] = val;
    }
    __syncthreads();

    if (oh >= OUT_H || ow >= OUT_W) return;

    // Accumulate for each output channel in this block
    float acc[OC_BLOCK];
    #pragma unroll
    for (int k = 0; k < OC_BLOCK; k++) {
        int oc = oc_start + k;
        acc[k] = (oc < OUT_C) ? bias[oc] : 0.0f;
    }

    // Shared memory offset for this thread's output position
    int sh_row = th * STRIDE;  // row offset in smem
    int sh_col = tw * STRIDE;  // col offset in smem

    #pragma unroll
    for (int ki = 0; ki < KH; ki++) {
        #pragma unroll
        for (int kj = 0; kj < KW; kj++) {
            float iv0 = smem[0][sh_row + ki][sh_col + kj];
            float iv1 = smem[1][sh_row + ki][sh_col + kj];
            float iv2 = smem[2][sh_row + ki][sh_col + kj];
            #pragma unroll
            for (int k = 0; k < OC_BLOCK; k++) {
                int oc = oc_start + k;
                if (oc < OUT_C) {
                    // weight layout: [OC, CIN, KH, KW]
                    const float* w = weight + oc * CIN * KH * KW + ki * KW + kj;
                    acc[k] += w[0 * KH * KW] * iv0
                            + w[1 * KH * KW] * iv1
                            + w[2 * KH * KW] * iv2;
                }
            }
        }
    }

    // Write outputs
    float* out_n = output + n * OUT_C * OUT_H * OUT_W;
    #pragma unroll
    for (int k = 0; k < OC_BLOCK; k++) {
        int oc = oc_start + k;
        if (oc < OUT_C) {
            out_n[oc * OUT_H * OUT_W + oh * OUT_W + ow] = acc[k];
        }
    }
}

torch::Tensor conv1_specialized_cuda(
    torch::Tensor input,
    torch::Tensor weight,
    torch::Tensor bias)
{
    TORCH_CHECK(input.is_cuda() && weight.is_cuda() && bias.is_cuda(), "All tensors must be CUDA");
    TORCH_CHECK(input.scalar_type() == torch::kFloat32, "Input must be float32");
    int N  = input.size(0);
    int IH = input.size(2);
    int IW = input.size(3);

    auto output = torch::empty({N, OUT_C, OUT_H, OUT_W}, input.options());

    int oc_blocks = (OUT_C + OC_BLOCK - 1) / OC_BLOCK;
    dim3 block(TILE_OW, TILE_OH, 1);
    dim3 grid(
        (OUT_W + TILE_OW - 1) / TILE_OW,
        (OUT_H + TILE_OH - 1) / TILE_OH,
        N * oc_blocks
    );

    conv1_direct_kernel<<<grid, block>>>(
        input.data_ptr<float>(),
        weight.data_ptr<float>(),
        bias.data_ptr<float>(),
        output.data_ptr<float>(),
        N, IH, IW
    );

    return output;
}
# <<<END_IMPROVE>>>
"""

class ModelNew(nn.Module):
    def __init__(self, num_classes=1000):
        super().__init__()
        # <<<IMPROVE:init_body>>>
        self.conv1 = nn.Conv2d(in_channels=3, out_channels=96, kernel_size=11, stride=4, padding=2)
        # <<<END_IMPROVE>>>

    def forward(self, x):
        # <<<IMPROVE:forward_stmt_1>>>
        # Fast path: shape-specialized custom CUDA kernel for the benchmark's first conv
        if (x.is_cuda and x.dtype == torch.float32 and x.dim() == 4
                and x.shape[1] == 3 and x.shape[2] == 224 and x.shape[3] == 224
                and self.conv1.weight.is_cuda and self.conv1.weight.dtype == torch.float32
                and self.conv1.bias is not None and self.conv1.bias.is_cuda
                and self.conv1.kernel_size == (11, 11)
                and self.conv1.stride == (4, 4)
                and self.conv1.padding == (2, 2)
                and self.conv1.dilation == (1, 1)
                and self.conv1.groups == 1):
            x = _stark_get_extension().conv1_specialized_cuda(
                x.contiguous(),
                self.conv1.weight.contiguous(),
                self.conv1.bias.contiguous()
            )
        else:
            x = self.conv1(x)
        # <<<END_IMPROVE>>>
        # <<<IMPROVE:forward_stmt_2>>>
        return x
        # <<<END_IMPROVE>>>

